parameters.functionCode:
const sessionId = $json.sessionId;
const latestMessage = $json.latestMessage;

if (!sessionId) {
  throw new Error('No sessionId provided in request body.');
}

const data = this.getWorkflowStaticData('global');

// Default phase
let phase = 1;

// If session exists, move to persuasion phase
if (data[sessionId]) {
  phase = 2;
} else {
  data[sessionId] = { phase: 1 };
}

return [{ json: { sessionId, phase, latestMessage } }];

parameters.prompt:
You are a WhatsApp automation demo bot.
If phase = 1: give a short, impressive reply that demonstrates instant capability to answer a customer.
If phase = 2: give a short reply that subtly persuades the user to consider using this automation for their business.

Phase: {{$json.phase}}
Latest user message: {{$json.latestMessage}}

Your reply should be one short sentence.
